import java.util.*;

public class Main {
    static int n;
    static long[] a, prefix;

    static long cost(long p) {
        int lo = 0, hi = n;  // count of centers <= p
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= p) lo = mid + 1; else hi = mid; }
        long count = lo;
        return 2 * (p * count - prefix[lo] + prefix[n] - prefix[lo] - p * (n - count));
    }

    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        n = r.nextInt();
        long budget = r.nextLong();
        a = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        Arrays.sort(a);
        prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        long middle = a[n / 2];
        if (cost(middle) > budget) { System.out.println(0); return; }
        long l = -1_000_000_000L, h = middle;
        while (l < h) {  // leftmost feasible position
            long mid = l + (h - l) / 2;
            if (cost(mid) <= budget) h = mid; else l = mid + 1;
        }
        long first = l;
        l = middle;
        h = 1_000_000_000L;
        while (l < h) {  // rightmost feasible position
            long mid = l + (h - l + 1) / 2;
            if (cost(mid) <= budget) l = mid; else h = mid - 1;
        }
        System.out.println(l - first + 1);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

