import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

func main() {
	n, budget := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	slices.Sort(a)
	prefix := make([]int, n+1)
	for i, v := range a {
		prefix[i+1] = prefix[i] + v
	}
	cost := func(p int) int {
		count := sort.Search(n, func(i int) bool { return a[i] > p }) // centers <= p
		return 2 * (p*count - prefix[count] + prefix[n] - prefix[count] - p*(n-count))
	}
	middle := a[n/2]
	if cost(middle) > budget {
		fmt.Println(0)
		return
	}
	l, r := -1_000_000_000, middle
	for l < r { // leftmost feasible position
		mid := l + (r-l)/2
		if cost(mid) <= budget {
			r = mid
		} else {
			l = mid + 1
		}
	}
	first := l
	l, r = middle, 1_000_000_000
	for l < r { // rightmost feasible position
		mid := l + (r-l+1)/2
		if cost(mid) <= budget {
			l = mid
		} else {
			r = mid - 1
		}
	}
	fmt.Println(l - first + 1)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
